import sys
import unittest
from pathlib import Path


sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "src"))

from utils.score_utils import (  # noqa: E402
    extract_score,
    is_binary_scale,
    normalize_score,
    parse_scale_bounds,
    score_is_within_scale,
)


class ScoreUtilsTest(unittest.TestCase):
    def test_extracts_multi_digit_decimal_score(self):
        self.assertEqual(extract_score("[RESULT] 10.5 [END]"), 10.5)

    def test_extracts_decimal_comma_score(self):
        self.assertEqual(extract_score("[RESULT] 3,5 [END]"), 3.5)

    def test_extracts_negative_score(self):
        self.assertEqual(extract_score("[RESULT] -2 [END]"), -2.0)

    def test_requires_complete_result_block(self):
        self.assertIsNone(extract_score("[RESULT] 4"))

    def test_parses_bounds_from_text_scale(self):
        rubrics = "1: Плохо\n\n3: Средне\n\n5: Отлично"
        self.assertEqual(parse_scale_bounds(rubrics), (1.0, 5.0))

    def test_parses_prompt_scale_template(self):
        prompt = """### Задание для оценки:
{instruction}

### Эталонный ответ:
{reference_answer}

### Ответ для оценки:
{answer}

### Критерий оценки:
{criteria_name}

### Шкала оценивания по критерию:
0: Предложение модели применимо только в одном случае либо не применимо вообще.
1: Предложение модели адаптировано под узкий спектр похожих ситуаций.
2: Предложение модели универсально и адаптировано под разные обстоятельства."""
        self.assertEqual(parse_scale_bounds(prompt), (0.0, 2.0))
        self.assertTrue(score_is_within_scale(2, prompt))
        self.assertFalse(score_is_within_scale(3, prompt))

    def test_parses_ascii_hyphen_scale(self):
        rubrics = "0 - Poor\n5 - Excellent"
        self.assertEqual(parse_scale_bounds(rubrics), (0.0, 5.0))

    def test_parses_named_range(self):
        self.assertEqual(
            parse_scale_bounds("Оцените по шкале от 1 до 10."),
            (1.0, 10.0),
        )

    def test_parses_bounds_from_nested_scale(self):
        rubrics = {"ru": {"-2": "Плохо", "0": "Средне", "2": "Хорошо"}}
        self.assertEqual(parse_scale_bounds(rubrics), (-2.0, 2.0))

    def test_accepts_score_above_two_when_scale_allows_it(self):
        rubrics = "1 — Плохо\n2 — Средне\n3 — Хорошо\n4 — Отлично"
        self.assertTrue(score_is_within_scale(4, rubrics))

    def test_rejects_score_outside_scale(self):
        rubrics = "1: Плохо\n2: Средне\n3: Отлично"
        self.assertFalse(score_is_within_scale(4, rubrics))

    def test_missing_scale_does_not_remove_valid_score(self):
        self.assertTrue(score_is_within_scale(4, None))

    def test_binary_scale_requires_exact_zero_and_one_values(self):
        self.assertTrue(is_binary_scale("0: Pass\n1: Reject"))
        self.assertFalse(is_binary_scale("1: Poor\n5: Excellent"))
        self.assertFalse(is_binary_scale("0: Poor\n1: Average\n2: Excellent"))

    def test_normalizes_score_by_scale_minimum_and_maximum(self):
        rubrics = "1: Poor\n3: Average\n5: Excellent"
        self.assertEqual(normalize_score(1, rubrics), 0.0)
        self.assertEqual(normalize_score(3, rubrics), 0.5)
        self.assertEqual(normalize_score(5, rubrics), 1.0)

    def test_normalizes_scale_with_zero_maximum(self):
        self.assertEqual(normalize_score(-1, "-1: Poor\n0: Excellent"), 0.0)
        self.assertEqual(normalize_score(0, "-1: Poor\n0: Excellent"), 1.0)

    def test_rejects_normalization_when_scale_has_no_range(self):
        with self.assertRaisesRegex(ValueError, "no range"):
            normalize_score(1, "1: Only value")


if __name__ == "__main__":
    unittest.main()

import json
import sys
import unittest
from pathlib import Path
from unittest.mock import mock_open, patch

import pandas as pd


sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "src"))

import metrics  # noqa: E402


class _Dataset:
    def __init__(self, rows):
        self._frame = pd.DataFrame(rows)

    def to_pandas(self):
        return self._frame


class MetricsTest(unittest.TestCase):
    def run_metrics(self, dataset_rows, scores):
        dataset = _Dataset(dataset_rows)
        with (
            patch.object(Path, "exists", return_value=True),
            patch("metrics.open", mock_open(read_data=json.dumps(scores))),
            patch.object(pd.DataFrame, "to_csv", autospec=True) as to_csv,
            patch.object(
                metrics.datasets,
                "load_dataset",
                return_value={"train": dataset},
            ),
        ):
            _, grand_mean = metrics.run(
                "model",
                Path("results"),
                dataset_path="dataset",
            )

        return to_csv.call_args.args[0], grand_mean

    def test_keeps_score_above_two_when_rubric_allows_it(self):
        # Two declared endpoints do not necessarily mean a binary 0/1 scale.
        rubrics = "1: Poor\n5: Excellent"
        dataset_rows = [
            {
                "prompt_id": 1,
                "meta": "general",
                "criteria": [
                    {"criteria_name": "quality", "rubrics": rubrics}
                ],
            },
            {
                "prompt_id": 2,
                "meta": "general",
                "criteria": [
                    {"criteria_name": "quality", "rubrics": rubrics}
                ],
            },
        ]
        scores = [
            {
                "response": "[FEEDBACK] ok [RESULT] 4 [END]",
                "meta": {"prompt_id": 1, "criteria_name": "quality"},
            },
            {
                "response": "[FEEDBACK] invalid [RESULT] 6 [END]",
                "meta": {"prompt_id": 2, "criteria_name": "quality"},
            },
        ]

        matrix, grand_mean = self.run_metrics(dataset_rows, scores)

        self.assertEqual(matrix.loc["quality", "general"], 0.75)
        self.assertEqual(grand_mean, 0.75)

    def test_binary_zero_allows_normalized_scores(self):
        dataset_rows = [
            {
                "prompt_id": 1,
                "meta": "general",
                "criteria": [
                    {"criteria_name": "gate", "rubrics": "0: Pass\n1: Reject"},
                    {
                        "criteria_name": "quality",
                        "rubrics": "0: Poor\n2: Excellent",
                    },
                ],
            }
        ]
        scores = [
            {
                "response": "[FEEDBACK] pass [RESULT] 0 [END]",
                "meta": {"prompt_id": 1, "criteria_name": "gate"},
            },
            {
                "response": "[FEEDBACK] ok [RESULT] 1 [END]",
                "meta": {"prompt_id": 1, "criteria_name": "quality"},
            },
        ]

        matrix, grand_mean = self.run_metrics(dataset_rows, scores)

        self.assertEqual(matrix.loc["quality", "general"], 0.5)
        self.assertEqual(grand_mean, 0.5)

    def test_binary_one_zeros_remaining_scores(self):
        dataset_rows = [
            {
                "prompt_id": 1,
                "meta": "general",
                "criteria": [
                    {"criteria_name": "gate", "rubrics": "0: Pass\n1: Reject"},
                    {
                        "criteria_name": "quality",
                        "rubrics": "0: Poor\n2: Excellent",
                    },
                ],
            }
        ]
        scores = [
            {
                "response": "[FEEDBACK] reject [RESULT] 1 [END]",
                "meta": {"prompt_id": 1, "criteria_name": "gate"},
            },
            {
                "response": "[FEEDBACK] excellent [RESULT] 2 [END]",
                "meta": {"prompt_id": 1, "criteria_name": "quality"},
            },
        ]

        matrix, grand_mean = self.run_metrics(dataset_rows, scores)

        self.assertEqual(matrix.loc["quality", "general"], 0.0)
        self.assertEqual(grand_mean, 0.0)


